func step(_dt: float) -> void:
	# Fixed inputs are deliberately immutable during this effect.
	pass

func _evaluate(data: Dictionary) -> Dictionary:
	var layers: Array = data.get("layers", [])
	var scores: Array[float] = []
	var peak := 0.0
	for layer in layers:
		var score := float(layer.get("height", 0.0)) * float(layer.get("control", 0.0))
		scores.append(score)
		peak = maxf(peak, score)
	var transition := maxf(float(data.get("transition", 0.0)), 1.0e-5)
	var raw: Array[float] = []
	var total := 0.0
	for i in layers.size():
		# Epsilon belongs to the competition before control multiplication.
		var competition := maxf(0.0, scores[i] - peak + transition)
		var value := (competition + 1.0e-6) * float(layers[i].get("control", 0.0))
		raw.append(value)
		total += value
	var denom := maxf(total, 1.0e-6)
	var weights: Array[float] = []
	for value in raw:
		weights.append(value / denom)
	var albedo := [0.0, 0.0, 0.0]
	var roughness := 0.0
	var metallic := 0.0
	var height := 0.0
	var normal := Vector3.ZERO
	for i in layers.size():
		var layer: Dictionary = layers[i]
		var w := weights[i]
		var color: Array = layer.get("albedo_linear", [0.0, 0.0, 0.0])
		for channel in 3:
			albedo[channel] += float(color[channel]) * w
		roughness += float(layer.get("roughness", 0.5)) * w
		metallic += float(layer.get("metallic", 0.0)) * w
		height += float(layer.get("height", 0.0)) * w
		var n: Array = layer.get("normal_ts", [0.0, 0.0, 1.0])
		normal += Vector3(float(n[0]), float(n[1]), float(n[2])) * w
	var base := _unit_or_up(normal)
	var final_normal := base
	if bool(data.get("detail_enabled", false)):
		var dn: Array = data.get("detail_normal_ts", [0.0, 0.0, 1.0])
		final_normal = _rnm(base, _unit_or_up(Vector3(float(dn[0]), float(dn[1]), float(dn[2]))))
	return {
		"weights": weights,
		"albedo_linear": albedo,
		"roughness_metallic_height": {"roughness": roughness, "metallic": metallic, "height": height},
		"base_normal_ts": [base.x, base.y, base.z],
		"final_normal_ts": [final_normal.x, final_normal.y, final_normal.z]
	}

func _unit_or_up(value: Vector3) -> Vector3:
	return value.normalized() if value.length_squared() > 1.0e-12 else Vector3(0, 0, 1)

func _rnm(base: Vector3, detail: Vector3) -> Vector3:
	# Reoriented Normal Mapping in tangent space.
	var result := Vector3(base.x * detail.z + detail.x * base.z,
		base.y * detail.z + detail.y * base.z,
		base.z * detail.z - base.x * detail.x - base.y * detail.y)
	return _unit_or_up(result)

