## Four-layer height competition.  The host remains responsible for scene selection.
var scene_root: Node
var test_input: Dictionary = {}
var cached: Dictionary = {}

func configure(root: Node, inputs: Dictionary) -> void:
	scene_root = root
	test_input = inputs
	cached = _evaluate(test_input)

func step(_dt: float) -> void:
	# Fixed inputs are deliberately immutable during this effect.
	pass

func _evaluate(data: Dictionary) -> Dictionary:
	var layers: Array = data.get("layers", [])
	var scores: Array[float] = []
	var peak := 0.0
	for layer in layers:
		var score := float(layer.get("height", 0.0)) * float(layer.get("control", 0.0))
		scores.append(score)
		peak = maxf(peak, score)
	var transition := maxf(float(data.get("transition", 0.0)), 1.0e-5)
	var raw: Array[float] = []
	var total := 0.0
	for i in layers.size():
		# Epsilon belongs to the competition before control multiplication.
		var competition := maxf(0.0, scores[i] - peak + transition)
		var value := (competition + 1.0e-6) * float(layers[i].get("control", 0.0))
		raw.append(value)
		total += value
	var denom := maxf(total, 1.0e-6)
	var weights: Array[float] = []
	for value in raw:
		weights.append(value / denom)
	var albedo := [0.0, 0.0, 0.0]
	var roughness := 0.0
	var metallic := 0.0
	var height := 0.0
	var normal := Vector3.ZERO
	for i in layers.size():
		var layer: Dictionary = layers[i]
		var w := weights[i]
		var color: Array = layer.get("albedo_linear", [0.0, 0.0, 0.0])
		for channel in 3:
			albedo[channel] += float(color[channel]) * w
		roughness += float(layer.get("roughness", 0.5)) * w
		metallic += float(layer.get("metallic", 0.0)) * w
		height += float(layer.get("height", 0.0)) * w
		var n: Array = layer.get("normal_ts", [0.0, 0.0, 1.0])
		normal += Vector3(float(n[0]), float(n[1]), float(n[2])) * w
	var base := _unit_or_up(normal)
	var final_normal := base
	if bool(data.get("detail_enabled", false)):
		var dn: Array = data.get("detail_normal_ts", [0.0, 0.0, 1.0])
		final_normal = _rnm(base, _unit_or_up(Vector3(float(dn[0]), float(dn[1]), float(dn[2]))))
	return {
		"weights": weights,
		"albedo_linear": albedo,
		"roughness_metallic_height": {"roughness": roughness, "metallic": metallic, "height": height},
		"base_normal_ts": [base.x, base.y, base.z],
		"final_normal_ts": [final_normal.x, final_normal.y, final_normal.z]
	}

func _unit_or_up(value: Vector3) -> Vector3:
	return value.normalized() if value.length_squared() > 1.0e-12 else Vector3(0, 0, 1)

func _rnm(base: Vector3, detail: Vector3) -> Vector3:
	# Reoriented Normal Mapping in tangent space.
	var result := Vector3(base.x * detail.z + detail.x * base.z,
		base.y * detail.z + detail.y * base.z,
		base.z * detail.z - base.x * detail.x - base.y * detail.y)
	return _unit_or_up(result)

func sample() -> Dictionary:
	return cached
"}

{"path":"effect/road.gdshader","content":"shader_type spatial;
render_mode diffuse_burley, specular_schlick_ggx;

uniform sampler2D stone_color : source_color, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D stone_normal : hint_normal, filter_linear_mipmap_anisotropic, repeat_enable;
uniform sampler2D stone_height : filter_linear_mipmap_anisotropic, repeat_enable;
uniform vec3 uv_scale = vec3(1.0);
uniform vec3 uv_offset = vec3(0.0);
uniform vec4 layer_height;
uniform vec4 layer_control;
uniform vec4 layer_roughness;
uniform vec4 layer_metallic;
uniform vec3 layer_color[4];
uniform vec3 layer_normal[4];
uniform float transition = 0.25;
uniform bool detail_enabled = false;
uniform vec3 detail_normal = vec3(0.0, 0.0, 1.0);
uniform float normal_strength = 1.0;

vec3 unit_normal(vec3 n) {
	return dot(n,n) > 1e-12 ? normalize(n) : vec3(0.0,0.0,1.0);
}
vec3 rnm(vec3 base, vec3 detail) {
	vec3 t = base + vec3(0.0,0.0,1.0);
	vec3 u = detail * vec3(-1.0,-1.0,1.0);
	if (t.z < 1e-6) { return vec3(detail.x,-detail.y,-detail.z); }
	return unit_normal(t * dot(t,u) / t.z - u);
}
vec4 competition(vec4 h, vec4 c) {
	vec4 score = h * c;
	float peak = max(max(score.x,score.y),max(score.z,score.w));
	vec4 raw = (max(score - vec4(peak) + vec4(max(transition,1e-5)),vec4(0.0)) + vec4(1e-6)) * c;
	return raw / max(dot(raw,vec4(1.0)),1e-6);
}
void fragment() {
	vec2 uv = UV * uv_scale.xy + uv_offset.xy;
	float h = texture(stone_height,uv).r;
	// The native wet-cobblestone surface assignment is the eligible-region mask.
	// Dry and wet stone share relief; mud occupies the complementary depressions.
	vec4 heights = layer_height * vec4(h,h,1.0-h,1.0);
	vec4 controls = layer_control * vec4(1.0,1.0,1.0-h,1.0);
	vec4 w = competition(heights,controls);
	vec3 tex_color = texture(stone_color,uv).rgb;
	vec3 stone_n = texture(stone_normal,uv).xyz * 2.0 - 1.0;
	stone_n.xy *= normal_strength;
	stone_n = unit_normal(stone_n);
	vec3 color = vec3(0.0);
	vec3 n = vec3(0.0);
	for (int i=0; i<4; i++) {
		// All layers use exactly the same competition weights for every channel.
		color += w[i] * layer_color[i] * tex_color / vec3(0.45,0.42,0.38);
		vec3 relief = stone_n;
		if (i == 1) { relief = unit_normal(mix(vec3(0.0,0.0,1.0),stone_n,0.75)); }
		if (i == 2) { relief = unit_normal(mix(vec3(0.0,0.0,1.0),stone_n,0.4)); }
		n += w[i] * rnm(relief, unit_normal(layer_normal[i]));
	}
	vec3 base = unit_normal(n);
	vec3 final_n = base;
	if (detail_enabled) { final_n = rnm(base,unit_normal(detail_normal)); }
	ALBEDO = color;
	ROUGHNESS = dot(w,layer_roughness);
	METALLIC = dot(w,layer_metallic);
	NORMAL_MAP = final_n * 0.5 + 0.5;
	NORMAL_MAP_DEPTH = 1.0;
}
"}

